from typing import List

class Solution:
    def scheduleCourse(self, courses: List[List[int]]) -> int:
        total = 0
        max_heap = []
        for duration, last_day in sorted(courses, key=lambda x: x[1]):
            total += duration
            heapq.heappush(max_heap, -duration)
            if total > last_day:
                total += heapq.heappop(max_heap)
        return len(max_heap)

