function scheduleCourse(courses) {
    courses.sort((a,b) => a[1]-b[1]);
    let total = 0;
    const heap = [];
    function push(x) {
        heap.push(x); let i=heap.length-1;
        while (i>0) { const p=Math.floor((i-1)/2); if (heap[p]>=heap[i]) break; [heap[p],heap[i]]=[heap[i],heap[p]]; i=p; }
    }
    function pop() {
        const top=heap[0], last=heap.pop();
        if (heap.length) { heap[0]=last; let i=0; while (true) { let l=2*i+1,r=l+1,b=i; if(l<heap.length&&heap[l]>heap[b])b=l; if(r<heap.length&&heap[r]>heap[b])b=r; if(b===i)break; [heap[i],heap[b]]=[heap[b],heap[i]]; i=b; } }
        return top;
    }
    for (const [d,end] of courses) { total+=d; push(d); if(total>end) total-=pop(); }
    return heap.length;
}

